pub fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    let n = numbers.len();
    if n <= 1 {
        return numbers;
    }

    // Result length must be 2*n - 1. Pre-allocate to avoid reallocations.
    let mut result = Vec::with_capacity(2 * n - 1);

    for (i, &x) in numbers.iter().enumerate() {
        if i > 0 {
            result.push(delimiter);
        }
        result.push(x);
    }

    result
}

